    "test": "node --test tests/*.test.mjs tests/long-jump/*.test.mjs tests/hurdles/*.test.mjs tests/reaction-rod/*.test.mjs tests/beer-slide/*.test.mjs tests/high-jump/*.test.mjs tests/pole-vault/*.test.mjs tests/shot-put/*.test.mjs tests/discus/*.test.mjs tests/tower-climb/*.test.mjs tests/sprint-100m/*.test.mjs tests/javelin/*.test.mjs tests/fast-hands/*.test.mjs",
    "check": "npm test && npm run build && node scripts/verify.mjs",
